def __getattr__(name):
    owner = _EXPORTS.get(name)
    if owner is not None:
        value = getattr(import_module("." + owner, __package__), name)
    elif name in _EXTERNAL:
        module, symbol = _EXTERNAL[name]
        module = import_module(module, __package__)
        value = getattr(module, symbol) if symbol is not None else module
    else:
        raise AttributeError(name)
    globals()[name] = value
    return value


def __dir__():
    return sorted(set(globals()) | set(_EXPORTS) | set(_EXTERNAL))
